    const destino = productos.find((p22) => p22.id === productoDestinoId);
    if (origen && destino && (!productoEsDelLocalActivo(origen) || !productoEsDelLocalActivo(destino))) return { ok: false, error: "Los dos productos deben pertenecer al local activo." };
    if (!origen || !destino) return { ok: false, error: "Alguno de los productos ya no existe." };
    const cantSale = Number(cantidadOrigen) || 0;
    const cantEntra = Number(cantidadDestino) || 0;
    if (cantSale <= 0 || cantEntra <= 0) return { ok: false, error: "Indica cu\xE1nto sale y cu\xE1nto entra." };
    if (cantSale > (Number(origen.stock) || 0)) {
      return { ok: false, error: `No hay tanto stock de ${origen.nombre}: quedan ${fmt(origen.stock)}.` };
    }
    const costoSale = cantSale * (Number(origen.costo) || 0);
    const costoEntra = cantEntra * (Number(destino.costo) || 0);
    const diferencia = costoEntra - costoSale;
    const operationId = uid();
    const rSale = aplicarMovimientoStock({
      productoId: productoOrigenId,
      cantidad: -cantSale,
      tipo: "AJUSTE_ENTRE_PRODUCTOS",
      operationId,
      movimientoId: uid(),
      origen: "ajustarProductoPorOtro",
      afectaStockTotal: true,
      permitirDeficit: false,
      motivo: `Cambiado por ${destino.nombre}${motivo ? " \xB7 " + motivo : ""}`
    });
    if (!rSale.ok) return rSale;
    const rEntra = aplicarMovimientoStock({
      productoId: productoDestinoId,
      cantidad: cantEntra,
      tipo: "AJUSTE_ENTRE_PRODUCTOS",
      operationId,
      movimientoId: uid(),
      origen: "ajustarProductoPorOtro",
      afectaStockTotal: true,
      permitirDeficit: true,
      motivo: `Viene de ${origen.nombre}${motivo ? " \xB7 " + motivo : ""}`
    });
    if (Math.abs(diferencia) >= 0.01 && addGasto) {
      addGasto({
        concepto: `Ajuste ${origen.nombre} \u2192 ${destino.nombre}${motivo ? " \xB7 " + motivo : ""}`,
        importe: Number((-diferencia).toFixed(2)),
        fecha: todayISO(),
        localId: origen.localId || destino.localId || localActivoId || null
      });
    }
    registrarAuditoria(
      "Ajuste entre productos",
      `${fmt(cantSale)} de ${origen.nombre} \u2192 ${fmt(cantEntra)} de ${destino.nombre} \xB7 diferencia \u20AC${fmt(Math.abs(diferencia))}${motivo ? " \xB7 " + motivo : ""}`
