          tipo: "OTRO",
          motivo: "Alta de producto con stock inicial",
          fecha: todayISO(),
          origen: "addProducto",
          documentoOrigenId: null,
          stockAnterior: 0,
          stockPosterior: stockInicial,
          afectaStockTotal: true,
          afectaStockPisoVenta: false,
          revierteMovimientoId: null
