      const stockTeoricoAntes = stockActual - deficitActual;
      const valorNuevo = stockNuevoForm;
      const dif = valorNuevo - stockTeoricoAntes;
      if (dif !== 0) {
        const { aplicarMovimientoStock: aplicarMovimientoStock2 } = crearMotorStock({ productos, setProductos, movimientos, setMovimientos, registrarAuditoria });
        aplicarMovimientoStock2({
          productoId: id,
          cantidad: dif,
          tipo: "INVENTARIO",
          movimientoId: uid(),
          origen: "updateProducto",
          afectaStockTotal: true,
          permitirDeficit: true,
          motivo: "Correcci\xF3n manual de stock"
        });
      }
    }
  }
  function deleteProducto(id) {
    const p22 = productos.find((x3) => x3.id === id);
    if (!productoEsDelLocalActivo(p22)) return false;
    registrarAuditoria("Eliminar producto (borrado l\xF3gico)", p22 ? p22.nombre : id);
    setProductos((s22) => s22.map((pr) => pr.id === id ? { ...pr, activo: false, eliminadoEn: todayISO() } : pr));
